class DefinitionParser(BaseParser):
    @property
    def language(self) -> str:
        return 'C'

    @property
    def id_attributes(self) -> Sequence[str]:
        return self.config.c_id_attributes

    @property
    def paren_attributes(self) -> Sequence[str]:
        return self.config.c_paren_attributes

    def _parse_string(self) -> str | None:
        if self.current_char != '"':
            return None
        start_pos = self.pos
        self.pos += 1
        escape = False
        while True:
            if self.eof:
                self.fail('Unexpected end during inside string.')
            elif self.current_char == '"' and not escape:
                self.pos += 1
                break
            elif self.current_char == '\\':
                escape = True
            else:
                escape = False
            self.pos += 1
        return self.definition[start_pos : self.pos]

    def _parse_literal(self) -> ASTLiteral | None:
        # -> integer-literal
        #  | character-literal
        #  | floating-literal
        #  | string-literal
        #  | boolean-literal -> "false" | "true"
        self.skip_ws()
        if self.skip_word('true'):
            return ASTBooleanLiteral(True)
        if self.skip_word('false'):
            return ASTBooleanLiteral(False)
        pos = self.pos
        if self.match(float_literal_re):
            self.match(float_literal_suffix_re)
            return ASTNumberLiteral(self.definition[pos : self.pos])
        for regex in (
            binary_literal_re,
            hex_literal_re,
            integer_literal_re,
            octal_literal_re,
        ):
            if self.match(regex):
                self.match(integers_literal_suffix_re)
                return ASTNumberLiteral(self.definition[pos : self.pos])

        string = self._parse_string()
        if string is not None:
            return ASTStringLiteral(string)

        # character-literal
        if self.match(char_literal_re):
            prefix = self.last_match.group(1)  # may be None when no prefix
            data = self.last_match.group(2)
            try:
                return ASTCharLiteral(prefix, data)
            except UnicodeDecodeError as e:
                self.fail(
                    'Can not handle character literal. Internal error was: %s' % e
                )
            except UnsupportedMultiCharacterCharLiteral:
                self.fail(
                    'Can not handle character literal'
                    ' resulting in multiple decoded characters.'
                )
        return None

    def _parse_paren_expression(self) -> ASTExpression | None:
        # "(" expression ")"
        if self.current_char != '(':
            return None
        self.pos += 1
        res = self._parse_expression()
        self.skip_ws()
        if not self.skip_string(')'):
            self.fail("Expected ')' in end of parenthesized expression.")
        return ASTParenExpr(res)

    def _parse_primary_expression(self) -> ASTExpression | None:
        # literal
        # "(" expression ")"
        # id-expression -> we parse this with _parse_nested_name
        self.skip_ws()
        res: ASTExpression | None = self._parse_literal()
        if res is not None:
            return res
        res = self._parse_paren_expression()
        if res is not None:
            return res
        nn = self._parse_nested_name()
        if nn is not None:
            return ASTIdExpression(nn)
        return None

    def _parse_initializer_list(
        self, name: str, open: str, close: str
    ) -> tuple[list[ASTExpression] | None, bool | None]:
        # Parse open and close with the actual initializer-list in between
        # -> initializer-clause '...'[opt]
        #  | initializer-list ',' initializer-clause '...'[opt]
        # TODO: designators
        self.skip_ws()
        if not self.skip_string_and_ws(open):
            return None, None
        if self.skip_string(close):
            return [], False

        exprs = []
        trailing_comma = False
        while True:
            self.skip_ws()
            expr = self._parse_expression()
            self.skip_ws()
            exprs.append(expr)
            self.skip_ws()
            if self.skip_string(close):
                break
            if not self.skip_string_and_ws(','):
                self.fail(f"Error in {name}, expected ',' or '{close}'.")
            if self.current_char == close == '}':
                self.pos += 1
                trailing_comma = True
                break
        return exprs, trailing_comma

    def _parse_paren_expression_list(self) -> ASTParenExprList | None:
        # -> '(' expression-list ')'
        # though, we relax it to also allow empty parens
        # as it's needed in some cases
        #
        # expression-list
        # -> initializer-list
        exprs, _trailing_comma = self._parse_initializer_list(
            'parenthesized expression-list', '(', ')'
        )
        if exprs is None:
            return None
        return ASTParenExprList(exprs)

    def _parse_braced_init_list(self) -> ASTBracedInitList | None:
        # -> '{' initializer-list ','[opt] '}'
        #  | '{' '}'
        exprs, trailing_comma = self._parse_initializer_list(
            'braced-init-list', '{', '}'
        )
        if exprs is None:
            return None
        return ASTBracedInitList(exprs, trailing_comma)

    def _parse_postfix_expression(self) -> ASTPostfixExpr:
        # -> primary
        #  | postfix "[" expression "]"
        #  | postfix "[" braced-init-list [opt] "]"
        #  | postfix "(" expression-list [opt] ")"
        #  | postfix "." id-expression  // taken care of in primary by nested name
        #  | postfix "->" id-expression
        #  | postfix "++"
        #  | postfix "--"

        prefix = self._parse_primary_expression()

        # and now parse postfixes
        post_fixes: list[ASTPostfixOp] = []
        while True:
            self.skip_ws()
            if self.skip_string_and_ws('['):
                expr = self._parse_expression()
                self.skip_ws()
                if not self.skip_string(']'):
                    self.fail("Expected ']' in end of postfix expression.")
                post_fixes.append(ASTPostfixArray(expr))
                continue
            if self.skip_string('->'):
                if self.skip_string('*'):
                    # don't steal the arrow
                    self.pos -= 3
                else:
                    name = self._parse_nested_name()
                    post_fixes.append(ASTPostfixMemberOfPointer(name))
                    continue
            if self.skip_string('++'):
                post_fixes.append(ASTPostfixInc())
                continue
            if self.skip_string('--'):
                post_fixes.append(ASTPostfixDec())
                continue
            lst = self._parse_paren_expression_list()
            if lst is not None:
                post_fixes.append(ASTPostfixCallExpr(lst))
                continue
            break
        return ASTPostfixExpr(prefix, post_fixes)

    def _parse_unary_expression(self) -> ASTExpression:
        # -> postfix
        #  | "++" cast
        #  | "--" cast
        #  | unary-operator cast -> (* | & | + | - | ! | ~) cast
        # The rest:
        #  | "sizeof" unary
        #  | "sizeof" "(" type-id ")"
        #  | "alignof" "(" type-id ")"
        self.skip_ws()
        for op in _expression_unary_ops:
            # TODO: hmm, should we be able to backtrack here?
            if op[0] in 'cn':
                res = self.skip_word(op)
            else:
                res = self.skip_string(op)
            if res:
                expr = self._parse_cast_expression()
                return ASTUnaryOpExpr(op, expr)
        if self.skip_word_and_ws('sizeof'):
            if self.skip_string_and_ws('('):
                typ = self._parse_type(named=False)
                self.skip_ws()
                if not self.skip_string(')'):
                    self.fail("Expecting ')' to end 'sizeof'.")
                return ASTSizeofType(typ)
            expr = self._parse_unary_expression()
            return ASTSizeofExpr(expr)
        if self.skip_word_and_ws('alignof'):
            if not self.skip_string_and_ws('('):
                self.fail("Expecting '(' after 'alignof'.")
            typ = self._parse_type(named=False)
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail("Expecting ')' to end 'alignof'.")
            return ASTAlignofExpr(typ)
        return self._parse_postfix_expression()

    def _parse_cast_expression(self) -> ASTExpression:
        # -> unary  | "(" type-id ")" cast
        pos = self.pos
        self.skip_ws()
        if self.skip_string('('):
            try:
                typ = self._parse_type(False)
                if not self.skip_string(')'):
                    self.fail("Expected ')' in cast expression.")
                expr = self._parse_cast_expression()
                return ASTCastExpr(typ, expr)
            except DefinitionError as ex_cast:
                self.pos = pos
                try:
                    return self._parse_unary_expression()
                except DefinitionError as ex_unary:
                    errs = [
                        (ex_cast, 'If type cast expression'),
                        (ex_unary, 'If unary expression'),
                    ]
                    raise self._make_multi_error(
                        errs, 'Error in cast expression.'
                    ) from ex_unary
        else:
            return self._parse_unary_expression()

    def _parse_logical_or_expression(self) -> ASTExpression:
        # logical-or     = logical-and      ||
        # logical-and    = inclusive-or     &&
        # inclusive-or   = exclusive-or     |
        # exclusive-or   = and              ^
        # and            = equality         &
        # equality       = relational       ==, !=
        # relational     = shift            <, >, <=, >=
        # shift          = additive         <<, >>
        # additive       = multiplicative   +, -
        # multiplicative = pm               *, /, %
        # pm             = cast             .*, ->*
        def _parse_bin_op_expr(self: DefinitionParser, op_id: int) -> ASTExpression:
            if op_id + 1 == len(_expression_bin_ops):
                parser = self._parse_cast_expression
            else:

                def parser() -> ASTExpression:
                    return _parse_bin_op_expr(self, op_id + 1)

            exprs = []
            ops = []
            exprs.append(parser())
            while True:
                self.skip_ws()
                pos = self.pos
                one_more = False
                for op in _expression_bin_ops[op_id]:
                    if op[0] in 'abcnox':
                        if not self.skip_word(op):
                            continue
                    else:
                        if not self.skip_string(op):
                            continue
                    if op == self.current_char == '&':
                        # don't split the && 'token'
                        self.pos -= 1
                        # and btw. && has lower precedence, so we are done
                        break
                    try:
                        expr = parser()
                        exprs.append(expr)
                        ops.append(op)
                        one_more = True
                        break
                    except DefinitionError:
                        self.pos = pos
                if not one_more:
                    break
            return ASTBinOpExpr(exprs, ops)  # type: ignore[return-value]

        return _parse_bin_op_expr(self, 0)

    def _parse_conditional_expression_tail(
        self, or_expr_head: Any
    ) -> ASTExpression | None:
        # -> "?" expression ":" assignment-expression
        return None

    def _parse_assignment_expression(self) -> ASTExpression:
        # -> conditional-expression
        #  | logical-or-expression assignment-operator initializer-clause
        # -> conditional-expression ->
        #     logical-or-expression
        #   | logical-or-expression "?" expression ":" assignment-expression
        #   | logical-or-expression assignment-operator initializer-clause
        exprs = []
        ops = []
        or_expr = self._parse_logical_or_expression()
        exprs.append(or_expr)
        # TODO: handle ternary with _parse_conditional_expression_tail
        while True:
            one_more = False
            self.skip_ws()
            for op in _expression_assignment_ops:
                if op[0] in 'abcnox':
                    if not self.skip_word(op):
                        continue
                else:
                    if not self.skip_string(op):
                        continue
                expr = self._parse_logical_or_expression()
                exprs.append(expr)
                ops.append(op)
                one_more = True
            if not one_more:
                break
        return ASTAssignmentExpr(exprs, ops)

    def _parse_constant_expression(self) -> ASTExpression:
        # -> conditional-expression
        or_expr = self._parse_logical_or_expression()
        # TODO: use _parse_conditional_expression_tail
        return or_expr

    def _parse_expression(self) -> ASTExpression:
        # -> assignment-expression
        #  | expression "," assignment-expression
        # TODO: actually parse the second production
        return self._parse_assignment_expression()

    def _parse_expression_fallback(
        self, end: list[str], parser: Callable[[], ASTExpression], allow: bool = True
    ) -> ASTExpression:
        # Stupidly "parse" an expression.
        # 'end' should be a list of characters which ends the expression.

        # first try to use the provided parser
        prev_pos = self.pos
        try:
            return parser()
        except DefinitionError as e:
            # some places (e.g., template parameters) we really don't want to use fallback,
            # and for testing we may want to globally disable it
            if not allow or not self.allowFallbackExpressionParsing:
                raise
            self.warn(
                'Parsing of expression failed. Using fallback parser.'
                ' Error was:\n%s' % e
            )
            self.pos = prev_pos
        # and then the fallback scanning
        assert end is not None
        self.skip_ws()
        start_pos = self.pos
        if self.match(_string_re):
            value = self.matched_text
        else:
            # TODO: add handling of more bracket-like things, and quote handling
            brackets = {'(': ')', '{': '}', '[': ']'}
            symbols: list[str] = []
            while not self.eof:
                if len(symbols) == 0 and self.current_char in end:
                    break
                if self.current_char in brackets:
                    symbols.append(brackets[self.current_char])
                elif len(symbols) > 0 and self.current_char == symbols[-1]:
                    symbols.pop()
                self.pos += 1
            if len(end) > 0 and self.eof:
                self.fail(
                    'Could not find end of expression starting at %d.' % start_pos
                )
            value = self.definition[start_pos : self.pos].strip()
        return ASTFallbackExpr(value.strip())

    def _parse_nested_name(self) -> ASTNestedName:
        names: list[Any] = []

        self.skip_ws()
        rooted = False
        if self.skip_string('.'):
            rooted = True
        while 1:
            self.skip_ws()
            if not self.match(identifier_re):
                self.fail('Expected identifier in nested name.')
            identifier = self.matched_text
            # make sure there isn't a keyword
            if identifier in _keywords:
                self.fail(
                    'Expected identifier in nested name, got keyword: %s' % identifier
                )
            if self.matched_text in self.config.c_extra_keywords:
                msg = (
                    'Expected identifier, got user-defined keyword: %s.'
                    ' Remove it from c_extra_keywords to allow it as identifier.\n'
                    'Currently c_extra_keywords is %s.'
                )
                self.fail(msg % (self.matched_text, str(self.config.c_extra_keywords)))
            ident = ASTIdentifier(identifier)
            names.append(ident)

            self.skip_ws()
            if not self.skip_string('.'):
                break
        return ASTNestedName(names, rooted)

    def _parse_simple_type_specifier(self) -> str | None:
        if self.match(_simple_type_specifiers_re):
            return self.matched_text
        for t in ('bool', 'complex', 'imaginary'):
            if t in self.config.c_extra_keywords:
                if self.skip_word(t):
                    return t
        return None

    def _parse_simple_type_specifiers(self) -> ASTTrailingTypeSpecFundamental | None:
        names: list[str] = []

        self.skip_ws()
        while True:
            t = self._parse_simple_type_specifier()
            if t is None:
                break
            names.append(t)
            self.skip_ws()
        if len(names) == 0:
            return None
        return ASTTrailingTypeSpecFundamental(names)

    def _parse_trailing_type_spec(self) -> ASTTrailingTypeSpec:
        # fundamental types, https://en.cppreference.com/w/c/language/type
        # and extensions
        self.skip_ws()
        res = self._parse_simple_type_specifiers()
        if res is not None:
            return res

        # prefixed
        prefix = None
        self.skip_ws()
        for k in ('struct', 'enum', 'union'):
            if self.skip_word_and_ws(k):
                prefix = k
                break

        nested_name = self._parse_nested_name()
        return ASTTrailingTypeSpecName(prefix, nested_name)

    def _parse_parameters(self, param_mode: str) -> ASTParameters | None:
        self.skip_ws()
        if not self.skip_string('('):
            if param_mode == 'function':
                self.fail('Expecting "(" in parameters.')
            else:
                return None

        args = []
        self.skip_ws()
        if not self.skip_string(')'):
            while 1:
                self.skip_ws()
                if self.skip_string('...'):
                    args.append(ASTFunctionParameter(None, True))
                    self.skip_ws()
                    if not self.skip_string(')'):
                        self.fail('Expected ")" after "..." in parameters.')
                    break
                # note: it seems that function arguments can always be named,
                # even in function pointers and similar.
                arg = self._parse_type_with_init(outer=None, named='single')
                # TODO: parse default parameters # TODO: didn't we just do that?

            args.append(ASTFunctionParameter(arg))

            self.skip_ws()
            if self.skip_string(','):
                continue
            if self.skip_string(')'):
                break
            self.fail(
                f'Expecting "," or ")" in parameters, got "{self.current_char}".'
            )

    attrs = self._parse_attribute_list()
    return ASTParameters(args, attrs)

def _parse_decl_specs_simple(
    self, outer: str | None, typed: bool
) -> ASTDeclSpecsSimple:
    """Just parse the simple ones."""
    storage = None
    thread_local = None
    inline = None
    restrict = None
    volatile = None
    const = None
    attrs = []
    while 1:  # accept any permutation of a subset of some decl-specs
        self.skip_ws()
        if not storage:
            if outer == 'member':
                if self.skip_word('auto'):
                    storage = 'auto'
                    continue
                if self.skip_word('register'):
                    storage = 'register'
                    continue
            if outer in {'member', 'function'}:
                if self.skip_word('static'):
                    storage = 'static'
                    continue
                if self.skip_word('extern'):
                    storage = 'extern'
                    continue
        if outer == 'member' and not thread_local:
            if self.skip_word('thread_local'):
                thread_local = 'thread_local'
                continue
            if self.skip_word('_Thread_local'):
                thread_local = '_Thread_local'
                continue
        if outer == 'function' and not inline:
            inline = self.skip_word('inline')
            if inline:
                continue

        if not restrict and typed:
            restrict = self.skip_word('restrict')
            if restrict:
                continue
        if not volatile and typed:
            volatile = self.skip_word('volatile')
            if volatile:
                continue
        if not const and typed:
            const = self.skip_word('const')
            if const:
                continue
        attr = self._parse_attribute()
        if attr:
            attrs.append(attr)
            continue
        break
    return ASTDeclSpecsSimple(
        storage,
        thread_local,
        inline,
        restrict,
        volatile,
        const,
        ASTAttributeList(attrs),
    )

def _parse_decl_specs(self, outer: str | None, typed: bool = True) -> ASTDeclSpecs:
    if outer:
        if outer not in {'type', 'member', 'function'}:
            raise Exception('Internal error, unknown outer "%s".' % outer)
    left_specs = self._parse_decl_specs_simple(outer, typed)
    right_specs = None

    if typed:
        trailing = self._parse_trailing_type_spec()
        right_specs = self._parse_decl_specs_simple(outer, typed)
    else:
        trailing = None
    return ASTDeclSpecs(outer, left_specs, right_specs, trailing)

def _parse_declarator_name_suffix(
    self, named: bool | str, param_mode: str, typed: bool
) -> ASTDeclarator:
    assert named in {True, False, 'single'}
    # now we should parse the name, and then suffixes
    if named == 'single':
        if self.match(identifier_re):
            if self.matched_text in _keywords:
                self.fail(
                    'Expected identifier, got keyword: %s' % self.matched_text
                )
            if self.matched_text in self.config.c_extra_keywords:
                msg = (
                    'Expected identifier, got user-defined keyword: %s. '
                    'Remove it from c_extra_keywords to allow it as identifier.\n'
                    'Currently c_extra_keywords is %s.'
                )
                self.fail(
                    msg % (self.matched_text, str(self.config.c_extra_keywords))
                )
            identifier = ASTIdentifier(self.matched_text)
            decl_id = ASTNestedName([identifier], rooted=False)
        else:
            decl_id = None
    elif named:
        decl_id = self._parse_nested_name()
    else:
        decl_id = None
    array_ops = []
    while 1:
        self.skip_ws()
        if typed and self.skip_string('['):
            self.skip_ws()
            static = False
            const = False
            volatile = False
            restrict = False
            while True:
                if not static:
                    if self.skip_word_and_ws('static'):
                        static = True
                        continue
                if not const:
                    if self.skip_word_and_ws('const'):
                        const = True
                        continue
                if not volatile:
                    if self.skip_word_and_ws('volatile'):
                        volatile = True
                        continue
                if not restrict:
                    if self.skip_word_and_ws('restrict'):
                        restrict = True
                        continue
                break
            vla = False if static else self.skip_string_and_ws('*')
            if vla:
                if not self.skip_string(']'):
                    self.fail("Expected ']' in end of array operator.")
                size = None
            else:
                if self.skip_string(']'):
                    size = None
                else:
                    parser = self._parse_expression
                    size = self._parse_expression_fallback([']'], parser)
                    self.skip_ws()
                    if not self.skip_string(']'):
                        self.fail("Expected ']' in end of array operator.")
            array_ops.append(ASTArray(static, const, volatile, restrict, vla, size))
        else:
            break
    param = self._parse_parameters(param_mode)
    if param is None and len(array_ops) == 0:
        # perhaps a bit-field
        if named and param_mode == 'type' and typed:
            self.skip_ws()
            if self.skip_string(':'):
                size = self._parse_constant_expression()
                return ASTDeclaratorNameBitField(declId=decl_id, size=size)
    return ASTDeclaratorNameParam(declId=decl_id, arrayOps=array_ops, param=param)

def _parse_declarator(
    self, named: bool | str, param_mode: str, typed: bool = True
) -> ASTDeclarator:
    # 'typed' here means 'parse return type stuff'
    if param_mode not in {'type', 'function'}:
        raise Exception("Internal error, unknown param_mode '%s'." % param_mode)
    prev_errors = []
    self.skip_ws()
    if typed and self.skip_string('*'):
        self.skip_ws()
        restrict = False
        volatile = False
        const = False
        attrs = []
        while 1:
            if not restrict:
                restrict = self.skip_word_and_ws('restrict')
                if restrict:
                    continue
            if not volatile:
                volatile = self.skip_word_and_ws('volatile')
                if volatile:
                    continue
            if not const:
                const = self.skip_word_and_ws('const')
                if const:
                    continue
            attr = self._parse_attribute()
            if attr is not None:
                attrs.append(attr)
                continue
            break
        next = self._parse_declarator(named, param_mode, typed)
        return ASTDeclaratorPtr(
            next=next,
            restrict=restrict,
            volatile=volatile,
            const=const,
            attrs=ASTAttributeList(attrs),
        )
    if typed and self.current_char == '(':  # note: peeking, not skipping
        # maybe this is the beginning of params, try that first,
        # otherwise assume it's noptr->declarator > ( ptr-declarator )
        pos = self.pos
        try:
            # assume this is params
            res = self._parse_declarator_name_suffix(named, param_mode, typed)
            return res
        except DefinitionError as ex_param_qual:
            msg = 'If declarator-id with parameters'
            if param_mode == 'function':
                msg += " (e.g., 'void f(int arg)')"
            prev_errors.append((ex_param_qual, msg))
            self.pos = pos
            try:
                assert self.current_char == '('
                self.skip_string('(')
                # TODO: hmm, if there is a name, it must be in inner, right?
                # TODO: hmm, if there must be parameters, they must b
                # inside, right?
                inner = self._parse_declarator(named, param_mode, typed)
                if not self.skip_string(')'):
                    self.fail('Expected \')\' in "( ptr-declarator )"')
                next = self._parse_declarator(
                    named=False, param_mode='type', typed=typed
                )
                return ASTDeclaratorParen(inner=inner, next=next)
            except DefinitionError as ex_no_ptr_paren:
                self.pos = pos
                msg = 'If parenthesis in noptr-declarator'
                if param_mode == 'function':
                    msg += " (e.g., 'void (*f(int arg))(double)')"
                prev_errors.append((ex_no_ptr_paren, msg))
                header = 'Error in declarator'
                raise self._make_multi_error(
                    prev_errors, header
                ) from ex_no_ptr_paren
    pos = self.pos
    try:
        return self._parse_declarator_name_suffix(named, param_mode, typed)
    except DefinitionError as e:
        self.pos = pos
        prev_errors.append((e, 'If declarator-id'))
        header = 'Error in declarator or parameters'
        raise self._make_multi_error(prev_errors, header) from e

def _parse_initializer(
    self, outer: str | None = None, allow_fallback: bool = True
) -> ASTInitializer | None:
    self.skip_ws()
    if outer == 'member' and False:  # NoQA: SIM223,TD005  # TODO
        braced_init = self._parse_braced_init_list()
        if braced_init is not None:
            return ASTInitializer(braced_init, hasAssign=False)

    if not self.skip_string('='):
        return None

    braced_init = self._parse_braced_init_list()
    if braced_init is not None:
        return ASTInitializer(braced_init)

    if outer == 'member':
        fallback_end: list[str] = []
    elif outer is None:  # function parameter
        fallback_end = [',', ')']
    else:
        self.fail(
            "Internal error, initializer for outer '%s' not implemented." % outer
        )

    def parser() -> ASTExpression:
        return self._parse_assignment_expression()

    value = self._parse_expression_fallback(
        fallback_end, parser, allow=allow_fallback
    )
    return ASTInitializer(value)

def _parse_type(self, named: bool | str, outer: str | None = None) -> ASTType:
    """named=False|'single'|True: 'single' is e.g., for function objects which
    doesn't need to name the arguments, but otherwise is a single name
    """
    if outer:  # always named
        if outer not in {'type', 'member', 'function'}:
            raise Exception('Internal error, unknown outer "%s".' % outer)
        assert named

    if outer == 'type':
        # We allow type objects to just be a name.
        prev_errors = []
        start_pos = self.pos
        # first try without the type
        try:
            decl_specs = self._parse_decl_specs(outer=outer, typed=False)
            decl = self._parse_declarator(named=True, param_mode=outer, typed=False)
            self.assert_end(allowSemicolon=True)
        except DefinitionError as ex_untyped:
            desc = 'If just a name'
            prev_errors.append((ex_untyped, desc))
            self.pos = start_pos
            try:
                decl_specs = self._parse_decl_specs(outer=outer)
                decl = self._parse_declarator(named=True, param_mode=outer)
            except DefinitionError as ex_typed:
                self.pos = start_pos
                desc = 'If typedef-like declaration'
                prev_errors.append((ex_typed, desc))
                # Retain the else branch for easier debugging.
                # TODO: it would be nice to save the previous stacktrace
                #       and output it here.
                if True:
                    header = 'Type must be either just a name or a '
                    header += 'typedef-like declaration.'
                    raise self._make_multi_error(prev_errors, header) from ex_typed
                else:
                    # For testing purposes.
                    # do it again to get the proper traceback (how do you
                    # reliably save a traceback when an exception is
                    # constructed?)
                    self.pos = start_pos
                    typed = True
                    decl_specs = self._parse_decl_specs(outer=outer, typed=typed)
                    decl = self._parse_declarator(
                        named=True, param_mode=outer, typed=typed
                    )
    elif outer == 'function':
        decl_specs = self._parse_decl_specs(outer=outer)
        decl = self._parse_declarator(named=True, param_mode=outer)
    else:
        param_mode = 'type'
        if outer == 'member':  # i.e., member
            named = True
        decl_specs = self._parse_decl_specs(outer=outer)
        decl = self._parse_declarator(named=named, param_mode=param_mode)
    return ASTType(decl_specs, decl)

def _parse_type_with_init(
    self, named: bool | str, outer: str | None
) -> ASTTypeWithInit:
    if outer:
        assert outer in {'type', 'member', 'function'}
    type = self._parse_type(outer=outer, named=named)
    init = self._parse_initializer(outer=outer)
    return ASTTypeWithInit(type, init)

def _parse_macro(self) -> ASTMacro:
    self.skip_ws()
    ident = self._parse_nested_name()
    if ident is None:
        self.fail('Expected identifier in macro definition.')
    self.skip_ws()
    if not self.skip_string_and_ws('('):
        return ASTMacro(ident, None)
    if self.skip_string(')'):
        return ASTMacro(ident, [])
    args = []
    while 1:
        self.skip_ws()
        if self.skip_string('...'):
            args.append(ASTMacroParameter(None, True))
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail('Expected ")" after "..." in macro parameters.')
            break
        if not self.match(identifier_re):
            self.fail('Expected identifier in macro parameters.')
        nn = ASTNestedName([ASTIdentifier(self.matched_text)], rooted=False)
        # Allow named variadic args:
        # https://gcc.gnu.org/onlinedocs/cpp/Variadic-Macros.html
        self.skip_ws()
        if self.skip_string_and_ws('...'):
            args.append(ASTMacroParameter(nn, False, True))
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail('Expected ")" after "..." in macro parameters.')
            break
        args.append(ASTMacroParameter(nn))
        if self.skip_string_and_ws(','):
            continue
        if self.skip_string_and_ws(')'):
            break
        self.fail("Expected identifier, ')', or ',' in macro parameter list.")
    return ASTMacro(ident, args)

def _parse_struct(self) -> ASTStruct:
    name = self._parse_nested_name()
    return ASTStruct(name)

def _parse_union(self) -> ASTUnion:
    name = self._parse_nested_name()
    return ASTUnion(name)

def _parse_enum(self) -> ASTEnum:
    name = self._parse_nested_name()
    return ASTEnum(name)

def _parse_enumerator(self) -> ASTEnumerator:
    name = self._parse_nested_name()
    attrs = self._parse_attribute_list()
    self.skip_ws()
    init = None
    if self.skip_string('='):
        self.skip_ws()
        parser = self._parse_constant_expression
        init_val = self._parse_expression_fallback([], parser)
        init = ASTInitializer(init_val)
    return ASTEnumerator(name, init, attrs)

def parse_declaration(self, objectType: str, directiveType: str) -> ASTDeclaration:
    object_type = objectType
    directive_type = directiveType
    if object_type not in {
        'function',
        'member',
        'macro',
        'struct',
        'union',
        'enum',
        'enumerator',
        'type',
    }:
        raise Exception('Internal error, unknown objectType "%s".' % object_type)
    if directive_type not in {
        'function',
        'member',
        'var',
        'macro',
        'struct',
        'union',
        'enum',
        'enumerator',
        'type',
    }:
        raise Exception(
            'Internal error, unknown directiveType "%s".' % directive_type
        )

    declaration: DeclarationType | None = None
    if object_type == 'member':
        declaration = self._parse_type_with_init(named=True, outer='member')
    elif object_type == 'function':
        declaration = self._parse_type(named=True, outer='function')
    elif object_type == 'macro':
        declaration = self._parse_macro()
    elif object_type == 'struct':
        declaration = self._parse_struct()
    elif object_type == 'union':
        declaration = self._parse_union()
    elif object_type == 'enum':
        declaration = self._parse_enum()
    elif object_type == 'enumerator':
        declaration = self._parse_enumerator()
    elif object_type == 'type':
        declaration = self._parse_type(named=True, outer='type')
    else:
        raise AssertionError
    if object_type != 'macro':
        self.skip_ws()
        semicolon = self.skip_string(';')
    else:
        semicolon = False
    return ASTDeclaration(object_type, directive_type, declaration, semicolon)

def parse_namespace_object(self) -> ASTNestedName:
    return self._parse_nested_name()

def parse_xref_object(self) -> ASTNestedName:
    name = self._parse_nested_name()
    # if there are '()' left, just skip them
    self.skip_ws()
    self.skip_string('()')
    self.assert_end()
    return name

def parse_expression(self) -> ASTExpression | ASTType:
    pos = self.pos
    res: ASTExpression | ASTType | None = None
    try:
        res = self._parse_expression()
        self.skip_ws()
        self.assert_end()
    except DefinitionError as ex_expr:
        self.pos = pos
        try:
            res = self._parse_type(False)
            self.skip_ws()
            self.assert_end()
        except DefinitionError as ex_type:
            header = 'Error when parsing (type) expression.'
            errs = [
                (ex_expr, 'If expression'),
                (ex_type, 'If type'),
            ]
            raise self._make_multi_error(errs, header) from ex_type
    return res

from __future__ import annotations

from typing import TYPE_CHECKING

from sphinx.domains.c._ast import (
    ASTDeclaration,
    ASTNestedName,
)
from sphinx.locale import __
from sphinx.util import logging

if TYPE_CHECKING:
    from collections.abc import Callable, Iterable, Iterator, Sequence
    from typing import Any, Self

    from sphinx.domains.c._ast import (
        ASTIdentifier,
    )
    from sphinx.environment import BuildEnvironment

logger = logging.getLogger(__name__)


class _DuplicateSymbolError(Exception):
    def __init__(self, symbol: Symbol, declaration: ASTDeclaration) -> None:
        assert symbol
        assert declaration
        self.symbol = symbol
        self.declaration = declaration

    def __str__(self) -> str:
        return 'Internal C duplicate symbol error:\n%s' % self.symbol.dump(0)


class SymbolLookupResult:
    __slots__ = 'symbols', 'parent_symbol', 'ident'

    symbols: Iterable[Symbol]
    parent_symbol: Symbol
    ident_or_op: ASTIdentifier

    def __init__(
        self, symbols: Iterable[Symbol], parent_symbol: Symbol, ident: ASTIdentifier
    ) -> None:
        self.symbols = symbols
        self.parent_symbol = parent_symbol
        self.ident = ident

    @property
    def parentSymbol(self) -> Symbol:
        return self.parent_symbol


class LookupKey:
    __slots__ = ('data',)

    data: Sequence[tuple[ASTIdentifier, str]]

    def __init__(self, data: Sequence[tuple[ASTIdentifier, str]], /) -> None:
        self.data = data

    def __repr__(self) -> str:
        return f'LookupKey({self.data!r})'

    def __str__(self) -> str:
        inner = ', '.join(f'({ident}, {id_})' for ident, id_ in self.data)
        return f'[{inner}]'


class Symbol:
    debug_indent = 0
    debug_indent_string = '  '
    debug_lookup = False
    debug_show_tree = False

    def __copy__(self) -> Self:
        raise AssertionError  # shouldn't happen

    def __deepcopy__(self, memo: Any) -> Symbol:
        if self.parent:
            raise AssertionError  # shouldn't happen
        # the domain base class makes a copy of the initial data, which is fine
        return Symbol(None, None, None, None, None)

    @staticmethod
    def debug_print(*args: Any) -> None:
        msg = Symbol.debug_indent_string * Symbol.debug_indent
        msg += ''.join(str(e) for e in args)
        logger.debug(msg)

    def _assert_invariants(self) -> None:
        if not self.parent:
            # parent == None means global scope, so declaration means a parent
            assert not self.declaration
            assert not self.docname
        else:
            if self.declaration:
                assert self.docname

    def __setattr__(self, key: str, value: Any) -> None:
        if key == 'children':
            raise AssertionError
        return super().__setattr__(key, value)

    def __init__(
        self,
        parent: Symbol | None,
        ident: ASTIdentifier | None,
        declaration: ASTDeclaration | None,
        docname: str | None,
        line: int | None,
    ) -> None:
        self.parent = parent
        # declarations in a single directive are linked together
        self.siblingAbove: Symbol | None = None
        self.siblingBelow: Symbol | None = None
        self.ident = ident
        self.declaration = declaration
        self.docname = docname
        self.line = line
        self.isRedeclaration = False
        self._assert_invariants()

        # These properties store the same children for different access patterns.
        # ``_add_child()`` and ``_remove_child()`` should be used for modifying them.
        self._children_by_name: dict[str, Symbol] = {}
        self._children_by_docname: dict[str, dict[str, Symbol]] = {}
        self._anon_children: set[Symbol] = set()

        if self.parent:
            self.parent._add_child(self)
        if self.declaration:
            self.declaration.symbol = self

        # Do symbol addition after self._children has been initialised.
        self._add_function_params()

    def __repr__(self) -> str:
        return f'<Symbol {self.to_string(indent=0)!r}>'

    @property
    def _children(self) -> Iterable[Symbol]:
        return self._children_by_name.values()

    def _add_child(self, child: Symbol) -> None:
        name = child.ident.name
        if name in self._children_by_name:
            # Duplicate so don't add - will be reported in _add_symbols()
            return
        self._children_by_name[name] = child
        self._children_by_docname.setdefault(child.docname, {})[name] = child
        if child.ident.is_anonymous:
            self._anon_children.add(child)

    def _remove_child(self, child: Symbol) -> None:
        name = child.ident.name
        self._children_by_name.pop(name, None)
        if children := self._children_by_docname.get(child.docname):
            children.pop(name, None)
        if child.ident.is_anonymous:
            self._anon_children.discard(child)

    def _fill_empty(self, declaration: ASTDeclaration, docname: str, line: int) -> None:
        self._assert_invariants()
        assert self.declaration is None
        assert self.docname is None
        assert self.line is None
        assert declaration is not None
        assert docname is not None
        assert line is not None
        self.declaration = declaration
        self.declaration.symbol = self
        self.docname = docname
        self.line = line
        self._assert_invariants()
        # and symbol addition should be done as well
        self._add_function_params()

    def _add_function_params(self) -> None:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_add_function_params:')
        # Note: we may be called from _fill_empty, so the symbols we want
        #       to add may actually already be present (as empty symbols).

        # add symbols for function parameters, if any
        if (
            self.declaration is not None
            and self.declaration.function_params is not None
        ):
            for p in self.declaration.function_params:
                if p.arg is None:
                    continue
                nn = p.arg.name
                if nn is None:
                    continue
                # (comparing to the template params: we have checked that we are a declaration)
                decl = ASTDeclaration('functionParam', None, p)
                assert not nn.rooted
                assert len(nn.names) == 1
                self._add_symbols(nn, decl, self.docname, self.line)
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 1

    def remove(self) -> None:
        if self.parent:
            self.parent._remove_child(self)
            self.parent = None

    def clear_doc(self, docname: str) -> None:
        if docname not in self._children_by_docname:
            for child in self._children:
                child.clear_doc(docname)
            return

        children: dict[str, Symbol] = self._children_by_docname.pop(docname)
        for child in children.values():
            child.declaration = None
            child.docname = None
            child.line = None
            if child.siblingAbove is not None:
                child.siblingAbove.siblingBelow = child.siblingBelow
            if child.siblingBelow is not None:
                child.siblingBelow.siblingAbove = child.siblingAbove
            child.siblingAbove = None
            child.siblingBelow = None
            self._remove_child(child)

    def get_all_symbols(self) -> Iterator[Symbol]:
        yield self
        for s_child in self._children:
            yield from s_child.get_all_symbols()

    @property
    def children(self) -> Iterator[Symbol]:
        yield from self._children

    def get_lookup_key(self) -> LookupKey:
        # The pickle files for the environment and for each document are distinct.
        # The environment has all the symbols, but the documents has xrefs that
        # must know their scope. A lookup key is essentially a specification of
        # how to find a specific symbol.
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        key = [
            # TODO: do we need the ID?
            (s.ident, None if s.declaration is None else s.declaration.get_newest_id())
            for s in reversed(symbols)
        ]
        return LookupKey(key)

    def get_full_nested_name(self) -> ASTNestedName:
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        symbols.reverse()
        names = [s.ident for s in symbols]
        return ASTNestedName(names, rooted=False)

    def _symbol_lookup(
        self,
        nested_name: ASTNestedName,
        on_missing_qualified_symbol: Callable[[Symbol, ASTIdentifier], Symbol | None],
        ancestor_lookup_type: str | None,
        match_self: bool,
        recurse_in_anon: bool,
        search_in_siblings: bool,
    ) -> SymbolLookupResult | None:
        # TODO: further simplification from C++ to C
        # ancestor_lookup_type: if not None, specifies the target type of the lookup
        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_symbol_lookup:')
            Symbol.debug_indent += 1
            Symbol.debug_print('self:')
            logger.debug(self.to_string(Symbol.debug_indent + 1, addEndNewline=False))
            Symbol.debug_print('nested_name:         ', nested_name)
            Symbol.debug_print('ancestor_lookup_type:', ancestor_lookup_type)
            Symbol.debug_print('match_self:          ', match_self)
            Symbol.debug_print('recurse_in_anon:     ', recurse_in_anon)
            Symbol.debug_print('search_in_siblings:  ', search_in_siblings)

        names = nested_name.names

        # find the right starting point for lookup
        parent_symbol = self
        if nested_name.rooted:
            while parent_symbol.parent is not None:
                parent_symbol = parent_symbol.parent

        if ancestor_lookup_type is not None:
            # walk up until we find the first identifier
            first_name = names[0]
            while parent_symbol.parent:
                if first_name.name in parent_symbol._children_by_name:
                    break
                parent_symbol = parent_symbol.parent

        if Symbol.debug_lookup:
            Symbol.debug_print('starting point:')
            logger.debug(
                parent_symbol.to_string(Symbol.debug_indent + 1, addEndNewline=False)
            )

        # and now the actual lookup
        for ident in names[:-1]:
            name = ident.name
            if name in parent_symbol._children_by_name:
                symbol = parent_symbol._children_by_name[name]
            else:
                symbol = on_missing_qualified_symbol(parent_symbol, ident)
                if symbol is None:
                    if Symbol.debug_lookup:
                        Symbol.debug_indent -= 2
                    return None
            parent_symbol = symbol

        if Symbol.debug_lookup:
            Symbol.debug_print('handle last name from:')
            logger.debug(
                parent_symbol.to_string(Symbol.debug_indent + 1, addEndNewline=False)
            )

        # handle the last name
        ident = names[-1]
        name = ident.name
        symbol = parent_symbol._children_by_name.get(name)
        if not symbol and recurse_in_anon:
            for child in parent_symbol._anon_children:
                if name in child._children_by_name:
                    symbol = child._children_by_name[name]
                    break

        if Symbol.debug_lookup:
            Symbol.debug_indent -= 2

        result = [symbol] if symbol else []
        return SymbolLookupResult(result, parent_symbol, ident)

    def _add_symbols(
        self,
        nested_name: ASTNestedName,
        declaration: ASTDeclaration | None,
        docname: str | None,
        line: int | None,
    ) -> Symbol:
        # TODO: further simplification from C++ to C
        # Used for adding a whole path of symbols, where the last may or may not
        # be an actual declaration.

        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_add_symbols:')
            Symbol.debug_indent += 1
            Symbol.debug_print('nn:       ', nested_name)
            Symbol.debug_print('decl:     ', declaration)
            Symbol.debug_print(f'location: {docname}:{line}')

        def on_missing_qualified_symbol(
            parent_symbol: Symbol, ident: ASTIdentifier
        ) -> Symbol:
            if Symbol.debug_lookup:
                Symbol.debug_indent += 1
                Symbol.debug_print('_add_symbols, on_missing_qualified_symbol:')
                Symbol.debug_indent += 1
                Symbol.debug_print('ident: ', ident)
                Symbol.debug_indent -= 2
            return Symbol(
                parent=parent_symbol,
                ident=ident,
                declaration=None,
                docname=None,
                line=None,
            )

        lookup_result = self._symbol_lookup(
            nested_name,
            on_missing_qualified_symbol,
            ancestor_lookup_type=None,
            match_self=False,
            recurse_in_anon=False,
            search_in_siblings=False,
        )
        # we create symbols all the way, so that can't happen
        assert lookup_result is not None
        symbols = list(lookup_result.symbols)
        if len(symbols) == 0:
            if Symbol.debug_lookup:
                Symbol.debug_print('_add_symbols, result, no symbol:')
                Symbol.debug_indent += 1
                Symbol.debug_print('ident:       ', lookup_result.ident)
                Symbol.debug_print('declaration: ', declaration)
                Symbol.debug_print(f'location:    {docname}:{line}')
                Symbol.debug_indent -= 1
            symbol = Symbol(

            parent=lookup_result.parent_symbol,
            ident=lookup_result.ident,
            declaration=declaration,
            docname=docname,
            line=line,
        )
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 2
        return symbol

    if Symbol.debug_lookup:
        Symbol.debug_print('_add_symbols, result, symbols:')
        Symbol.debug_indent += 1
        Symbol.debug_print('number symbols:', len(symbols))
        Symbol.debug_indent -= 1

    if not declaration:
        if Symbol.debug_lookup:
            Symbol.debug_print('no declaration')
            Symbol.debug_indent -= 2
        # good, just a scope creation
        # TODO: what if we have more than one symbol?
        return symbols[0]

    no_decl = []
    with_decl = []
    dup_decl = []
    for s in symbols:
        if s.declaration is None:
            no_decl.append(s)
        elif s.isRedeclaration:
            dup_decl.append(s)
        else:
            with_decl.append(s)
    if Symbol.debug_lookup:
        Symbol.debug_print('#no_decl:  ', len(no_decl))
        Symbol.debug_print('#with_decl:', len(with_decl))
        Symbol.debug_print('#dup_decl: ', len(dup_decl))

    # With partial builds we may start with a large symbol tree stripped of declarations.
    # Essentially any combination of no_decl, with_decl, and dup_decls seems possible.
    # TODO: make partial builds fully work. What should happen when the primary symbol gets
    #  deleted, and other duplicates exist? The full document should probably be rebuild.

    # First check if one of those with a declaration matches.
    # If it's a function, we need to compare IDs,
    # otherwise there should be only one symbol with a declaration.

    if len(with_decl) == 0:
        cand_symbol = None
    else:
        cand_symbol = self._make_cand_symbol(
            lookup_result, declaration, docname, line
        )

        if declaration.objectType != 'function':
            assert len(with_decl) <= 1
            self._handle_duplicate_declaration(
                with_decl[0], cand_symbol, declaration
            )
            # (not reachable)

        # a function, so compare IDs
        cand_id = declaration.get_newest_id()
        if Symbol.debug_lookup:
            Symbol.debug_print('cand_id:', cand_id)
        for symbol in with_decl:
            old_id = symbol.declaration.get_newest_id()
            if Symbol.debug_lookup:
                Symbol.debug_print('old_id: ', old_id)
            if cand_id == old_id:
                self._handle_duplicate_declaration(symbol, cand_symbol, declaration)
                # (not reachable)
        # no candidate symbol found with matching ID
    # if there is an empty symbol, fill that one
    if len(no_decl) == 0:
        if Symbol.debug_lookup:
            Symbol.debug_print(
                'no match, no empty, cand_sybmol is not None?:',
                cand_symbol is not None,
            )
            Symbol.debug_indent -= 2
        if cand_symbol is not None:
            return cand_symbol
        else:
            return self._make_cand_symbol(lookup_result, declaration, docname, line)
    else:
        if Symbol.debug_lookup:
            Symbol.debug_print(
                'no match, but fill an empty declaration, cand_sybmol is not None?:',
                cand_symbol is not None,
            )
            Symbol.debug_indent -= 2
        if cand_symbol is not None:
            cand_symbol.remove()
        # assert len(no_decl) == 1
        # TODO: enable assertion when we at some point find out how to do cleanup
        # for now, just take the first one, it should work fine ... right?
        symbol = no_decl[0]
        # If someone first opened the scope, and then later
        # declares it, e.g,
        # .. namespace:: Test
        # .. namespace:: nullptr
        # .. class:: Test
        symbol._fill_empty(declaration, docname, line)
        return symbol

@staticmethod
def _make_cand_symbol(
    lookup_result: SymbolLookupResult,
    declaration: ASTDeclaration | None,
    docname: str | None,
    line: int | None,
) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_print('begin: creating candidate symbol')
    symbol = Symbol(
        parent=lookup_result.parent_symbol,
        ident=lookup_result.ident,
        declaration=declaration,
        docname=docname,
        line=line,
    )
    if Symbol.debug_lookup:
        Symbol.debug_print('end:   creating candidate symbol')
    return symbol

@staticmethod
def _handle_duplicate_declaration(
    symbol: Symbol, cand_symbol: Symbol, declaration: ASTDeclaration
) -> None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('redeclaration')
        Symbol.debug_indent -= 1
        Symbol.debug_indent -= 2
    # Redeclaration of the same symbol.
    # Let the new one be there, but raise an error to the client
    # so it can use the real symbol as subscope.
    # This will probably result in a duplicate id warning.
    cand_symbol.isRedeclaration = True
    raise _DuplicateSymbolError(symbol, declaration)

def merge_with(
    self, other: Symbol, docnames: list[str], env: BuildEnvironment
) -> None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('merge_with:')

    assert other is not None
    for other_child in other._children:
        other_name = other_child.ident.name
        if other_name not in self._children_by_name:
            # TODO: hmm, should we prune by docnames?
            other_child.parent = self
            self._add_child(other_child)
            other_child._assert_invariants()
            continue
        our_child = self._children_by_name[other_name]
        if other_child.declaration and other_child.docname in docnames:
            if not our_child.declaration:
                our_child._fill_empty(
                    other_child.declaration, other_child.docname, other_child.line
                )
            elif our_child.docname != other_child.docname:
                name = str(our_child.declaration)
                msg = __(
                    'Duplicate C declaration, also defined at %s:%s.\n'
                    "Declaration is '.. c:%s:: %s'."
                )
                logger.warning(
                    msg,
                    our_child.docname,
                    our_child.line,
                    our_child.declaration.directiveType,
                    name,
                    location=(other_child.docname, other_child.line),
                    type='duplicate_declaration',
                    subtype='c',
                )
            else:
                # Both have declarations, and in the same docname.
                # This can apparently happen, it should be safe to
                # just ignore it, right?
                pass
        our_child.merge_with(other_child, docnames, env)

    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1

def add_name(self, nestedName: ASTNestedName) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('add_name:')
    res = self._add_symbols(nestedName, declaration=None, docname=None, line=None)
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1
    return res

def add_declaration(
    self, declaration: ASTDeclaration, docname: str, line: int
) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('add_declaration:')
    assert declaration is not None
    assert docname is not None
    assert line is not None
    nested_name = declaration.name
    res = self._add_symbols(nested_name, declaration, docname, line)
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1
    return res

def find_identifier(
    self,
    ident: ASTIdentifier,
    matchSelf: bool,
    recurseInAnon: bool,
    searchInSiblings: bool,
) -> Symbol | None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('find_identifier:')
        Symbol.debug_indent += 1
        Symbol.debug_print('ident:           ', ident)
        Symbol.debug_print('matchSelf:       ', matchSelf)
        Symbol.debug_print('recurseInAnon:   ', recurseInAnon)
        Symbol.debug_print('searchInSiblings:', searchInSiblings)
        logger.debug(self.to_string(Symbol.debug_indent + 1, addEndNewline=False))
        Symbol.debug_indent -= 2
    current = self
    while current is not None:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 2
            Symbol.debug_print('trying:')
            logger.debug(
                current.to_string(Symbol.debug_indent + 1, addEndNewline=False)
            )
            Symbol.debug_indent -= 2
        if matchSelf and current.ident == ident:
            return current
        name = ident.name
        if name in current._children_by_name:
            return current._children_by_name[name]
        if recurseInAnon:
            for child in current._anon_children:
                if name in child._children_by_name:
                    return child._children_by_name[name]
        if not searchInSiblings:
            break
        current = current.siblingAbove
    return None

def direct_lookup(self, key: LookupKey) -> Symbol | None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('direct_lookup:')
        Symbol.debug_indent += 1
    s = self
    for ident, id_ in key.data:
        s = s._children_by_name.get(ident.name)
        if Symbol.debug_lookup:
            Symbol.debug_print('name:          ', ident.name)
            Symbol.debug_print('id:            ', id_)
            if s is not None:
                logger.debug(
                    s.to_string(Symbol.debug_indent + 1, addEndNewline=False)
                )
            else:
                Symbol.debug_print('not found')
        if s is None:
            break
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 2
    return s

def find_declaration(
    self, nestedName: ASTNestedName, typ: str, matchSelf: bool, recurseInAnon: bool
) -> Symbol | None:
    # templateShorthand: missing template parameter lists for templates is ok
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('find_declaration:')

    def on_missing_qualified_symbol(
        parent_symbol: Symbol, ident: ASTIdentifier
    ) -> Symbol | None:
        return None

    lookup_result = self._symbol_lookup(
        nestedName,
        on_missing_qualified_symbol,
        ancestor_lookup_type=typ,
        match_self=matchSelf,
        recurse_in_anon=recurseInAnon,
        search_in_siblings=False,
    )
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1
    if lookup_result is None:
        return None

    symbols = list(lookup_result.symbols)
    if len(symbols) == 0:
        return None
    return symbols[0]

def to_string(self, indent: int, *, addEndNewline: bool = True) -> str:
    res = [Symbol.debug_indent_string * indent]
    if not self.parent:
        res.append('::')
    else:
        if self.ident:
            res.append(self.ident.name)
        else:
            res.append(str(self.declaration))
        if self.declaration:
            res.append(': ')
            if self.isRedeclaration:
                res.append('!!duplicate!! ')
            res.append(str(self.declaration))
    if self.docname:
        res.extend((
            '\t(',
            self.docname,
            ')',
        ))
    if addEndNewline:
        res.append('\n')
    return ''.join(res)

def dump(self, indent: int) -> str:
    return ''.join([
        self.to_string(indent),
        *(c.dump(indent + 1) for c in self._children),
    ])

from __future__ import annotations

from typing import TYPE_CHECKING

from sphinx.domains.cpp._ast import (
    ASTDeclaration,
    ASTNestedName,
    ASTNestedNameElement,
)
from sphinx.locale import __
from sphinx.util import logging

if TYPE_CHECKING:
    from collections.abc import Callable, Iterable, Iterator, Sequence
    from typing import Any, NoReturn

    from sphinx.domains.cpp._ast import (
        ASTIdentifier,
        ASTOperator,
        ASTTemplateArgs,
        ASTTemplateDeclarationPrefix,
        ASTTemplateIntroduction,
        ASTTemplateParams,
    )
    from sphinx.environment import BuildEnvironment

logger = logging.getLogger(__name__)


class _DuplicateSymbolError(Exception):
    def __init__(self, symbol: Symbol, declaration: ASTDeclaration) -> None:
        assert symbol
        assert declaration
        self.symbol = symbol
        self.declaration = declaration

    def __str__(self) -> str:
        return 'Internal C++ duplicate symbol error:\n%s' % self.symbol.dump(0)


class _QualifiedSymbolIsTemplateParam(Exception):
    pass


class SymbolLookupResult:
    __slots__ = (
        'symbols',
        'parent_symbol',
        'ident_or_op',
        'template_params',
        'template_args',
    )

    symbols: Iterable[Symbol]
    parent_symbol: Symbol
    ident_or_op: ASTIdentifier | ASTOperator
    template_params: Any
    template_args: ASTTemplateArgs

    def __init__(
        self,
        symbols: Iterable[Symbol],
        parent_symbol: Symbol,
        ident_or_op: ASTIdentifier | ASTOperator,
        template_params: Any,
        template_args: ASTTemplateArgs,
    ) -> None:
        self.symbols = symbols
        self.parent_symbol = parent_symbol
        self.ident_or_op = ident_or_op
        self.template_params = template_params
        self.template_args = template_args

    @property
    def parentSymbol(self) -> Symbol:
        return self.parent_symbol

    @property
    def identOrOp(self) -> ASTIdentifier | ASTOperator:
        return self.ident_or_op

    @property
    def templateParams(self) -> Any:
        return self.template_params

    @property
    def templateArgs(self) -> ASTTemplateArgs:
        return self.template_args


class LookupKey:
    __slots__ = ('data',)

    data: Sequence[
        tuple[
            ASTNestedNameElement,
            ASTTemplateParams | ASTTemplateIntroduction,
            str | None,
        ]
    ]

    def __init__(
        self,
        data: Sequence[
            tuple[
                ASTNestedNameElement,
                ASTTemplateParams | ASTTemplateIntroduction,
                str | None,
            ]
        ],
        /,
    ) -> None:
        self.data = data

    def __repr__(self) -> str:
        return f'LookupKey({self.data!r})'

    def __str__(self) -> str:
        inner = ', '.join(f'({ident}, {id_})' for ident, _, id_ in self.data)
        return f'[{inner}]'


def _is_specialization(
    template_params: ASTTemplateParams | ASTTemplateIntroduction,
    template_args: ASTTemplateArgs,
) -> bool:
    # Checks if `template_args` does not exactly match `template_params`.
    # the names of the template parameters must be given exactly as args
    # and params that are packs must in the args be the name expanded
    if len(template_params.params) != len(template_args.args):
        return True
    # having no template params and no arguments is also a specialization
    if len(template_params.params) == 0:
        return True
    for i in range(len(template_params.params)):
        param = template_params.params[i]
        arg = template_args.args[i]
        # TODO: doing this by string manipulation is probably not the most efficient
        param_name = str(param.name)
        arg_txt = str(arg)
        is_arg_pack_expansion = arg_txt.endswith('...')
        if param.isPack != is_arg_pack_expansion:
            return True
        arg_name = arg_txt[:-3] if is_arg_pack_expansion else arg_txt
        if param_name != arg_name:
            return True
    return False


class Symbol:
    debug_indent = 0
    debug_indent_string = '  '
    debug_lookup = False  # overridden by the corresponding config value
    debug_show_tree = False  # overridden by the corresponding config value

    def __copy__(self) -> NoReturn:
        raise AssertionError  # shouldn't happen

    def __deepcopy__(self, memo: Any) -> Symbol:
        if self.parent:
            raise AssertionError  # shouldn't happen
        # the domain base class makes a copy of the initial data, which is fine
        return Symbol(None, None, None, None, None, None, None)

    @staticmethod
    def debug_print(*args: Any) -> None:
        logger.debug(Symbol.debug_indent_string * Symbol.debug_indent, end='')
        logger.debug(*args)

    def _assert_invariants(self) -> None:
        if not self.parent:
            # parent == None means global scope, so declaration means a parent
            assert not self.identOrOp
            assert not self.templateParams
            assert not self.templateArgs
            assert not self.declaration
            assert not self.docname
        else:
            if self.declaration:
                assert self.docname

    def __setattr__(self, key: str, value: Any) -> None:
        if key == 'children':
            raise AssertionError
        return super().__setattr__(key, value)

    def __init__(
        self,
        parent: Symbol | None,
        identOrOp: ASTIdentifier | ASTOperator | None,
        templateParams: ASTTemplateParams | ASTTemplateIntroduction | None,
        templateArgs: Any,
        declaration: ASTDeclaration | None,
        docname: str | None,
        line: int | None,
    ) -> None:
        self.parent = parent
        # declarations in a single directive are linked together
        self.siblingAbove: Symbol | None = None
        self.siblingBelow: Symbol | None = None
        self.identOrOp = identOrOp
        # Ensure the same symbol for `A` is created for:
        #
        #     .. cpp:class:: template <typename T> class A
        #
        # and
        #
        #     .. cpp:function:: template <typename T> int A<T>::foo()
        if templateArgs is not None and not _is_specialization(
            templateParams, templateArgs
        ):
            templateArgs = None
        self.templateParams = templateParams  # template<templateParams>
        self.templateArgs = templateArgs  # identifier<templateArgs>
        self.declaration = declaration
        self.docname = docname
        self.line = line
        self.isRedeclaration = False
        self._assert_invariants()

        # Remember to modify Symbol.remove if modifications to the parent change.
        self._children: list[Symbol] = []
        self._anon_children: list[Symbol] = []
        # note: _children includes _anon_children
        if self.parent:
            self.parent._children.append(self)
        if self.declaration:
            self.declaration.symbol = self

        # Do symbol addition after self._children has been initialised.
        self._add_template_and_function_params()

    def __repr__(self) -> str:
        return f'<Symbol {self.to_string(indent=0)!r}>'

    def _fill_empty(self, declaration: ASTDeclaration, docname: str, line: int) -> None:
        self._assert_invariants()
        assert self.declaration is None
        assert self.docname is None
        assert self.line is None
        assert declaration is not None
        assert docname is not None
        assert line is not None
        self.declaration = declaration
        self.declaration.symbol = self
        self.docname = docname
        self.line = line
        self._assert_invariants()
        # and symbol addition should be done as well
        self._add_template_and_function_params()

    def _add_template_and_function_params(self) -> None:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_add_template_and_function_params:')
        # Note: we may be called from _fill_empty, so the symbols we want
        #       to add may actually already be present (as empty symbols).

        # add symbols for the template params
        if self.templateParams:
            for tp in self.templateParams.params:
                if not tp.get_identifier():
                    continue
                # only add a declaration if we our self are from a declaration
                if self.declaration:
                    decl = ASTDeclaration(objectType='templateParam', declaration=tp)
                else:
                    decl = None
                nne = ASTNestedNameElement(tp.get_identifier(), None)
                nn = ASTNestedName([nne], [False], rooted=False)
                self._add_symbols(nn, [], decl, self.docname, self.line)
        # add symbols for function parameters, if any
        if (
            self.declaration is not None
            and self.declaration.function_params is not None
        ):
            for fp in self.declaration.function_params:
                if fp.arg is None:
                    continue
                nn = fp.arg.name
                if nn is None:
                    continue
                # (comparing to the template params: we have checked that we are a declaration)
                decl = ASTDeclaration(objectType='functionParam', declaration=fp)
                assert not nn.rooted
                assert len(nn.names) == 1
                self._add_symbols(nn, [], decl, self.docname, self.line)
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 1

    def remove(self) -> None:
        if self.parent is None:
            return
        assert self in self.parent._children
        self.parent._children.remove(self)
        self.parent = None

    def clear_doc(self, docname: str) -> None:
        new_children: list[Symbol] = []
        for s_child in self._children:
            s_child.clear_doc(docname)
            if s_child.declaration and s_child.docname == docname:
                s_child.declaration = None
                s_child.docname = None
                s_child.line = None
                if s_child.siblingAbove is not None:
                    s_child.siblingAbove.siblingBelow = s_child.siblingBelow
                if s_child.siblingBelow is not None:
                    s_child.siblingBelow.siblingAbove = s_child.siblingAbove
                s_child.siblingAbove = None
                s_child.siblingBelow = None
            new_children.append(s_child)
        self._children = new_children

    def get_all_symbols(self) -> Iterator[Any]:
        yield self
        for s_child in self._children:
            yield from s_child.get_all_symbols()

    @property
    def children_recurse_anon(self) -> Iterator[Symbol]:
        for c in self._children:
            yield c
            if not c.identOrOp.is_anon():
                continue

            yield from c.children_recurse_anon

    def get_lookup_key(self) -> LookupKey:
        # The pickle files for the environment and for each document are distinct.
        # The environment has all the symbols, but the documents has xrefs that
        # must know their scope. A lookup key is essentially a specification of
        # how to find a specific symbol.
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        key = [
            (
                ASTNestedNameElement(s.identOrOp, s.templateArgs),
                s.templateParams,
                None if s.declaration is None else s.declaration.get_newest_id(),
            )
            for s in reversed(symbols)
        ]
        return LookupKey(key)

    def get_full_nested_name(self) -> ASTNestedName:
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        symbols.reverse()
        names = []
        templates = []
        for s in symbols:
            names.append(ASTNestedNameElement(s.identOrOp, s.templateArgs))
            templates.append(False)
        return ASTNestedName(names, templates, rooted=False)

    def _find_first_named_symbol(
        self,
        ident_or_op: ASTIdentifier | ASTOperator,
        template_params: ASTTemplateParams | ASTTemplateIntroduction,
        template_args: ASTTemplateArgs | None,
        template_shorthand: bool,
        match_self: bool,
        recurse_in_anon: bool,
        correct_primary_template_args: bool,
    ) -> Symbol | None:
        if Symbol.debug_lookup:
            Symbol.debug_print('_find_first_named_symbol ->')
        res = self._find_named_symbols(
            ident_or_op,
            template_params,
            template_args,
            template_shorthand,
            match_self,
            recurse_in_anon,
            correct_primary_template_args,
            search_in_siblings=False,
        )
        try:
            return next(res)
        except StopIteration:
            return None

    def _find_named_symbols(
        self,
        ident_or_op: ASTIdentifier | ASTOperator,
        template_params: ASTTemplateParams | ASTTemplateIntroduction,
        template_args: ASTTemplateArgs,
        template_shorthand: bool,
        match_self: bool,
        recurse_in_anon: bool,
        correct_primary_template_args: bool,
        search_in_siblings: bool,
    ) -> Iterator[Symbol]:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_find_named_symbols:')
            Symbol.debug_indent += 1
            Symbol.debug_print('self:')
            logger.debug(self.to_string(Symbol.debug_indent + 1), end='')
            Symbol.debug_print('ident_or_op:                  ', ident_or_op)
            Symbol.debug_print('template_params:              ', template_params)
            Symbol.debug_print('template_args:                ', template_args)
            Symbol.debug_print('template_shorthand:           ', template_shorthand)
            Symbol.debug_print('match_self:                   ', match_self)
            Symbol.debug_print('recurse_in_anon:              ', recurse_in_anon)
            Symbol.debug_print(
                'correct_primary_template_args:', correct_primary_template_args
            )
            Symbol.debug_print('search_in_siblings:           ', search_in_siblings)

        if correct_primary_template_args:
            if template_params is not None and template_args is not None:
                # If both are given, but it's not a specialization, then do lookup as if
                # there is no argument list.
                # For example: template<typename T> int A<T>::var;
                if not _is_specialization(template_params, template_args):
                    template_args = None

        for s in self._candidates(
            match_self=match_self, recurse_in_anon=recurse_in_anon
        ):
            if Symbol.debug_lookup:
                Symbol.debug_print('candidate:')
                logger.debug(s.to_string(Symbol.debug_indent + 1), end='')
            if self._matches(
                s,
                ident_or_op=ident_or_op,
                template_params=template_params,
                template_args=template_args,
                template_shorthand=template_shorthand,
            ):
                if Symbol.debug_lookup:
                    Symbol.debug_indent += 1
                    Symbol.debug_print('matches')
                    Symbol.debug_indent -= 3
                yield s
                if Symbol.debug_lookup:
                    Symbol.debug_indent += 2
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 2

    @staticmethod
    def _matches(
